bool IsGroupResEnough() {
    bool enough = false;
    if (strict_group_size_) {
        enough = static_cast<int>(group_map_.size()) == group_capacity_ &&
             enough_group_count_ == group_capacity_;
    } else {
        enough = static_cast<int>(group_map_.size()) == group_capacity_;
    }
    return enough;
}

